/* PDFwise service worker — generated by scripts/pwa.mjs from scripts/sw-template.js. */
/* eslint-disable no-restricted-globals */

const VERSION = '__VERSION__'
const PRECACHE = __PRECACHE__
const CORE = `pdfwise-core-${VERSION}`
const RUNTIME = 'pdfwise-runtime' // OCR engine + language data, web fonts
const SHARE = 'pdfwise-share' // files shared into the installed app, until the page picks them up

// Third-party files the app loads on demand. Cached on first use so OCR and fonts work offline.
const RUNTIME_HOSTS = ['cdn.jsdelivr.net', 'unpkg.com', 'tessdata.projectnaptha.com', 'fonts.googleapis.com', 'fonts.gstatic.com']

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CORE)
      // One by one, so a single failed file doesn't throw away everything else.
      const results = await Promise.allSettled(
        PRECACHE.map(async (url) => {
          const res = await fetch(url, { cache: 'reload' })
          if (!res.ok) throw new Error(`${url}: ${res.status}`)
          await cache.put(url, res)
        }),
      )
      const failed = results.filter((r) => r.status === 'rejected').length
      if (failed) console.warn(`[sw] ${failed} of ${PRECACHE.length} files could not be cached`)
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys()
      await Promise.all(keys.filter((k) => k.startsWith('pdfwise-core-') && k !== CORE).map((k) => caches.delete(k)))
      await self.clients.claim()
      const clients = await self.clients.matchAll({ type: 'window' })
      clients.forEach((c) => c.postMessage({ type: 'OFFLINE_READY', version: VERSION }))
    })(),
  )
})

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting()
})

self.addEventListener('fetch', (event) => {
  const req = event.request
  const url = new URL(req.url)

  if (req.method === 'POST' && url.origin === location.origin && url.pathname === '/share-target') {
    event.respondWith(receiveShare(req))
    return
  }
  if (req.method !== 'GET') return

  if (url.origin === location.origin) {
    if (url.pathname.startsWith('/api/')) return // conversions always need the server
    if (req.mode === 'navigate') {
      event.respondWith(page(req, url))
      return
    }
    if (url.pathname.startsWith('/assets/')) {
      event.respondWith(cacheFirst(req, CORE))
      return
    }
    event.respondWith(staleWhileRevalidate(req, CORE))
    return
  }

  if (RUNTIME_HOSTS.includes(url.hostname)) event.respondWith(cacheFirst(req, RUNTIME))
})

/** Pages: network first (so deploys show up), cached copy when offline. */
async function page(req, url) {
  const key = url.pathname.replace(/\.html$/, '').replace(/\/+$/, '') || '/'
  try {
    const res = await fetch(req)
    if (res.ok && res.type === 'basic') {
      const cache = await caches.open(CORE)
      cache.put(key, res.clone())
    }
    return res
  } catch {
    const cached = (await caches.match(key, { ignoreSearch: true, ignoreVary: true })) || (await caches.match('/', { ignoreSearch: true, ignoreVary: true }))
    return cached || new Response('<h1>You’re offline</h1><p>Open PDFwise once while online so it can work offline.</p>', { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } })
  }
}

async function cacheFirst(req, name) {
  // ignoreVary: servers often send `Vary: Origin`, and module scripts carry an Origin header
  // that the precache requests didn't. Built files are content-hashed, so this is safe.
  const cached = await caches.match(req, { ignoreVary: true })
  if (cached) return cached
  const res = await fetch(req)
  // Opaque (no-cors) responses are fine to keep for scripts and fonts loaded from CDNs.
  if (res.ok || res.type === 'opaque') {
    const cache = await caches.open(name)
    cache.put(req, res.clone())
  }
  return res
}

async function staleWhileRevalidate(req, name) {
  const cache = await caches.open(name)
  const cached = await cache.match(req, { ignoreSearch: true, ignoreVary: true })
  const network = fetch(req)
    .then((res) => {
      if (res.ok) cache.put(req, res.clone())
      return res
    })
    .catch(() => cached)
  return cached || network
}

/** Files shared from another app (Android share sheet): park them, then open the home page. */
async function receiveShare(req) {
  try {
    const form = await req.formData()
    const cache = await caches.open(SHARE)
    for (const key of await cache.keys()) await cache.delete(key)
    const files = form.getAll('files').filter((f) => f && typeof f === 'object' && f.size > 0)
    await Promise.all(
      files.map((f, i) =>
        cache.put(`/__shared/${i}`, new Response(f, { headers: { 'Content-Type': f.type || 'application/octet-stream', 'X-File-Name': encodeURIComponent(f.name || `file-${i + 1}`) } })),
      ),
    )
    const text = [form.get('url'), form.get('text'), form.get('title')].filter(Boolean).join(' ')
    if (text) await cache.put('/__shared/text', new Response(String(text)))
  } catch (e) {
    console.warn('[sw] share failed', e)
  }
  return Response.redirect('/?shared=1', 303)
}
